using System;

public record BankTransaction(string TxId, decimal Amount, DateTime CreatedAt);

public class Program
{
    public static void Main()
    {
        var txAsli = new BankTransaction("TX-999", 500_000m, DateTime.UtcNow);
        var txDuplikat = new BankTransaction("TX-999", 500_000m, txAsli.CreatedAt);

        Console.WriteLine($"Apakah txAsli == txDuplikat? {txAsli == txDuplikat}");

        // Mutasi Non-Destruktif dengan 'with'
        var txReversal = txAsli with { Amount = -txAsli.Amount };
        Console.WriteLine($"Tx Asli    : {txAsli.TxId} sebesar Rp {txAsli.Amount:N0}");
        Console.WriteLine($"Tx Reversal: {txReversal.TxId} sebesar Rp {txReversal.Amount:N0}");

        // Dekonstruksi Positional Record ke Variabel Terpisah
        var (id, nominal, waktu) = txAsli;
        Console.WriteLine($"Dekonstruksi -> ID: {id}, Nominal: {nominal:N0}");
    }
}

