using System;

public record OrderRecord(string OrderId, decimal TotalAmount, string Status);

public class OrderManager
{
    public static OrderRecord ApproveOrder(OrderRecord order)
    {
        if (order == null) throw new ArgumentNullException(nameof(order));
        if (string.Equals(order.Status, "Pending", StringComparison.OrdinalIgnoreCase))
        {
            return order with { Status = "Approved" };
        }
        return order;
    }

    public static void Main()
    {
        var o1 = new OrderRecord("ORD-101", 250000m, "Pending");
        var o2 = ApproveOrder(o1);
        Console.WriteLine($"Order 1: {o1.Status}");
        Console.WriteLine($"Order 2: {o2.Status}");
    }
}
